def main():
    print("Loading payload from:", PAYLOAD_PATH)
    with open(PAYLOAD_PATH, "r", encoding="utf-8") as f:
        data = json.load(f)

    questions = data.get("questions", [])
    print(f"Total questions in payload: {len(questions)}")

    enriched_count = 0
    for idx, patch in ENRICHMENTS_BATCH1.items():
        if idx >= len(questions):
            print(f"Index {idx} out of range!")
            continue
        q = questions[idx]

        q["question_fa"] = patch["q_fa"]
        q["options_fa"] = patch["opts"]
        q["correct_index"] = patch["ci"]
        q["options_why_fa"] = patch["whys"]
        q["explanation_fa"] = patch["exp"]
        if "golden" in patch:
            q["golden_fa"] = patch["golden"]
        enriched_count += 1

    with open(PAYLOAD_PATH, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)

    print(f"Successfully enriched {enriched_count} questions in {PAYLOAD_PATH}.")

if __name__ == "__main__":
    main()
